/*
 * sincqed -- Sinc (trapezoid in z = ln s) evaluation of QED vertex graphs contributing to the
 *            electron anomalous magnetic moment, with Volkov's pointwise forest subtraction.
 *            The graph kernels are generated by generator/ (Python, optional).
 *
 * Usage:
 *   sincqed list
 *   sincqed run h N [eps] [top] GRAPH...     GRAPH = name (g3_07), Volkov string ("3; 1-6, 2-5, 4-7"),
 *                                            or a group: all2 all3 all4 q3 vp3 vp4 lbl lbl4 pi6
 *   sincqed scale GRAPH [kappa] [seed]       scaling (finiteness) test of the subtracted integrand
 *   sincqed compare RESULTS_h RESULTS_h2    per-graph error |S(h)-S(h2)|/3 from two results files (h2 ~ 1.2h)
 *
 *   h    : Sinc step in z                     N  : points per dimension, |z| <= (N-1)h/2; the half-width
 *                                              (N-1)/2 is rounded UP to a multiple of 2^(top+1), with a note
 *   eps  : pruning tolerance (default 1e-11)  top: coarsest level 2^top h (default: 2 if 4h <= 3,
 *          else 1; SINCQED_TOPSTEP changes the 3.  A coarse step much wider than the integrand's
 *          features loses whole patches that no eps recovers: g3_21 at h=1.5, step 4h, is 2e-3 low
 *          even at eps=1e-11, while step 2h gives the converged value already at eps=1e-8)
 *
 * Grid: plain, z_i = k_i h with |k_i| <= K.  Environment:
 *   SINCQED_GROW=0   full-box coarse scan instead of the support-following one
 *   SINCQED_PREDICT=alpha  skip final-level points whose predicted |f| (mean over the corners of the 2h
 *                    cube they sit in) is below alpha times the keep threshold (sum.c); use with eps 10x smaller
 *   SINCQED_SYM=0 | p0,..,p{D-1}  symmetry fold, on by default (found automatically): 0 turns it off, or name the involution (sum.c)
 *   SINCQED_DROPUNRES=0  keep the values of points unresolved even in the high-precision type (eval.c)
 *   SINCQED_PACK=0   evaluate one point at a time instead of several in the SIMD lanes (eval.c)
 *   SINCQED_HIST=prefix, SINCQED_DUMP=prefix: term-size histograms, evaluated points (sum.c)
 *   SINCQED_CKPT     seconds between checkpoints (default 600, 0 = off); SINCQED_CKPT_DIR (default .)
 *   SINCQED_LOG, SINCQED_RESULTS, SINCQED_PROGRESS: log file, results file ("-" = none), progress interval
 *
 * Errors: disc ~ 2|S_2h-S_h|^2/sum|f| (a loose bound); pruned = weight dropped at every level;
 * trunc = outer shell of the top-level scan continued geometrically; round = eps*sum|terms| of the
 * points still unresolved after the high-precision recomputation, in quadrature.  The realistic
 * error is |S(h)-S(1.2h)|/3 + round (sincqed compare).
 * Values include the mirror graph (Volkov's convention) and are coefficients of (alpha/pi)^L.
 */
#include "sq.h"

static void run_graph(const graph_t *g, double h, int N, double eps, int top, double *tot, double *toterr, double *toterr2){
    CURNAME = g->name;
    lattice_setup(g, h, N, top);
    say("  [%6.0fs]  graph %d/%d %s (%s, D=%d) started%s\n", wtime() - T0, CURI, CURN, g->name, g->volkov, g->D, USEGPU ? " on the GPU" : "");
    ABSKIPPED = ABMISS = 0; UNRESDROP = 0;
    res_t R = hsum(g, h, N, eps, top);
    double w = g->weight, v = w*R.S[0], d2 = fabs(R.S[1]-R.S[0]);
    double disc = R.Ah > 0 ? 2*d2*d2/R.Ah : 0;
    double err = w*(disc + R.prune + R.trunc + R.unres);
    say("%-7s %-22s D=%d w=%d  %+.12f  err %.2e (disc %.1e prune %.1e trunc %.1e round %.1e)  |S2h-Sh| %.1e  S_4h %+.6f  evals %ld quad %ld kept %ld  %.1fs",
           g->name, g->volkov, g->D, g->weight, v, err, w*disc, w*R.prune, w*R.trunc, w*R.unres, w*d2, w*R.S[2], R.nev, R.nq, R.kept_top, R.t);
    const ref_t *r = findref(g->volkov);
    if(r) say("  ref %+.12f (%s) diff %+.2e", r->val, r->src, v - r->val);
    say("\n");
    say("# %s: fallback when eps*sum|terms| > %.1e per point (max of G2_ABSERR and SINCQED_ABREL*eps*Ref; SINCQED_DDSLACK %g)\n", g->name, ABSERR, DDSLACK);
    if(ABSKIP) say("# %s: %ld of %ld evaluations skipped the |.| sums (no fallback check)%s\n", g->name, ABSKIPPED, R.nev,
                   ABCHECK ? "" : "");
    if(UNRESDROP){
        say("# WARNING %s: %ld points unresolved even in %s (eps*sum|terms| > |value|, not one digit left) %s; their bound is in the round column\n",
            g->name, UNRESDROP, QNAME, DROPUNRES ? "counted as 0 (SINCQED_DROPUNRES=0 keeps them)" : "kept as they came out");
    }
    if(ABCHECK) say("# %s: SINCQED_ABCHECK: %ld of the skipped points would have needed the fallback\n", g->name, ABMISS);
    if(RESF){
        fprintf(RESF, "%-8s %-28s %d %d %d %5.3f %4d %8.1e %d %+.15e %.3e %.2e %.2e %.2e %.2e %+.8e %12ld %9.1f",
                g->name, g->volkov, g->L, g->D, g->weight, h, 2*K+1, eps, top, v, err, w*disc, w*R.prune, w*R.trunc, w*R.unres, w*R.S[1], R.nev, R.t);
        if(r) fprintf(RESF, " %+.15e %+.3e", r->val, v - r->val); else fprintf(RESF, " %22s %10s", "-", "-");
        fprintf(RESF, "\n"); fflush(RESF);
    }
    *tot += v; *toterr += err; *toterr2 += err*err;
}

/* scaling test: x_i -> x_i rho^{e_i}, e_i in {-E..E} (env SCALE_E, default 1); integrand*measure must
 * vanish as kappa grows along every direction */
static void scale_test(const graph_t *g, double kap, unsigned seed){
    int n = g->n, fixed = g->fixed; srand(seed);
    QREAL x0[16];
    for(int i = 0; i < n; i++) x0[i] = (QREAL)exp(4.0*rand()/RAND_MAX - 2.0);
    x0[fixed] = 1;
    int E = getenv("SCALE_E") ? atoi(getenv("SCALE_E")) : 1, B = 2*E+1;   /* exponents -E..E */
    int nfree = n-1; long ndir = 1; for(int i = 0; i < nfree; i++) ndir *= B;
    int bad = 0; double worst = 0, wv[3] = {0}; long worstd = -1; int we[16] = {0};
    #pragma omp parallel for schedule(dynamic,8)
    for(long d = 0; d < ndir; d++){
        QREAL x[16];
        int e[16], nz = 0; long r = d;
        for(int i = 0; i < n; i++){ if(i == fixed){ e[i] = 0; continue; } e[i] = (int)(r % B) - E; r /= B; nz += e[i] != 0; }
        if(!nz) continue;
        double gv[3];
        for(int q = 0; q < 3; q++){
            double kk = kap*(q+1)/3.0; QREAL meas = 1;
            for(int i = 0; i < n; i++){ x[i] = x0[i]*(QREAL)exp(-kk*e[i]); if(i != fixed) meas *= x[i]; }
            QREAL ab; QREAL v = g->ptq(x, 0, &ab);
            gv[q] = fabs((double)(v*meas));
        }
        double ratio = gv[1] > 0 ? gv[2]/gv[1] : 0;
        #pragma omp critical
        {
        if(ratio > worst){ worst = ratio; worstd = d; wv[0] = gv[0]; wv[1] = gv[1]; wv[2] = gv[2]; memcpy(we, e, sizeof e); }
        if(ratio > 0.3 && gv[2] > 1e-30){
            if(bad < 12){ printf("  slow direction e=("); for(int i = 0; i < n; i++) if(i != fixed) printf("%+d", e[i]);
                printf(")  |g| at kappa/3,2/3,1: %.3e %.3e %.3e\n", gv[0], gv[1], gv[2]); }
            bad++;
        }
        }
    }
    printf("%-6s %-22s scale test kappa=%g: %ld directions, %d slow (ratio>0.3), worst ratio %.3g (dir %ld: e=(",
           g->name, g->volkov, kap, ndir-1, bad, worst, worstd);
    for(int i = 0; i < n; i++) if(i != fixed) printf("%+d", we[i]);
    printf(") |g| %.2e %.2e %.2e)\n", wv[0], wv[1], wv[2]);
}

/* ---------------- compare: error from two runs at h and a larger step ---------------- */
typedef struct { char name[32]; double h, v, rnd; } cres_t;
static int read_results(const char *fn, cres_t *r, int max){
    FILE *f = fopen(fn, "r"); if(!f){ perror(fn); return -1; }
    char line[4096]; int n = 0;
    while(fgets(line, sizeof line, f)){
        if(line[0] == '#') continue;
        char *tok[64]; int nt = 0;
        for(char *t = strtok(line, " \t\n"); t && nt < 64; t = strtok(NULL, " \t\n")) tok[nt++] = t;
        int iv = -1;
        for(int i = 1; i < nt; i++) if((tok[i][0] == '+' || tok[i][0] == '-') && strlen(tok[i]) >= 20 && strchr(tok[i], 'e')){ iv = i; break; }
        if(iv < 5 || iv + 5 >= nt) continue;
        int j; for(j = 0; j < n; j++) if(!strcmp(r[j].name, tok[0])) break;   /* a later line replaces an earlier one */
        if(j == n){ if(n == max) continue; n++; }
        snprintf(r[j].name, sizeof r[j].name, "%s", tok[0]);
        r[j].h = atof(tok[iv-4]); r[j].v = atof(tok[iv]); r[j].rnd = atof(tok[iv+5]);
    }
    fclose(f); return n;
}
static int compare(const char *fa, const char *fb){
    static cres_t A[2048], B[2048];
    int na = read_results(fa, A, 2048), nb = read_results(fb, B, 2048);
    if(na < 0 || nb < 0) return 1;
    printf("# compare %s and %s: value from the smaller step h; error = |S(h) - S(h')|/3 + round\n", fa, fb);
    printf("# (calibrated on graph 16, LbL and the Pi2 Pi2 chain with h = 1.0, h' = 1.2: true error <= |dS|/3)\n");
    printf("# %-8s %6s %6s  %22s  %10s  %10s\n", "name", "h", "h'", "value", "dS", "error");
    double tot = 0, e1 = 0, e2 = 0; int m = 0;
    for(int i = 0; i < na; i++) for(int j = 0; j < nb; j++) if(!strcmp(A[i].name, B[j].name)){
        cres_t *f = A[i].h <= B[j].h ? &A[i] : &B[j], *c = A[i].h <= B[j].h ? &B[j] : &A[i];
        if(f->h == c->h){ printf("  %-8s same h in both files, skipped\n", f->name); break; }
        double d = f->v - c->v, e = fabs(d)/3 + f->rnd;
        printf("  %-8s %6.3f %6.3f  %+22.15e  %+10.2e  %10.2e\n", f->name, f->h, c->h, f->v, d, e);
        tot += f->v; e1 += e; e2 += e*e; m++; break;
    }
    printf("# SUM %d graphs  %+.12f  err %.2e (in quadrature)  %.2e (linear)\n", m, tot, sqrt(e2), e1);
    return 0;
}

/* graphs named on the command line (names, Volkov strings or groups), in order, without repeats */
static int select_graphs(int argc, char **argv, int a, const graph_t ***out){
    const graph_t **sel = (const graph_t**)malloc((NALL + 1)*sizeof *sel); int ns = 0;
    for(int b = a; b < argc; b++){
        int hit = 0;
        for(int i = 0; i < NALL; i++){
            if(!selected(ALL[i], argv[b])) continue; hit = 1;
            int dup = 0; for(int j = 0; j < ns; j++) dup |= sel[j] == ALL[i];
            if(!dup) sel[ns++] = ALL[i];
        }
        if(!hit) fprintf(stderr, "# no graph matches %s in this build\n", argv[b]);
    }
    *out = sel; return ns;
}

/* eps and top are taken only from purely numeric arguments, so a graph name missing from the build is
   reported instead of being read as a number */
static int isnum(const char *s){ char *e; strtod(s, &e); return e != s && *e == 0; }

void face_register(void);
int main(int argc, char **argv){
    register_graphs(); face_register();
    if(getenv("G2_ABSERR")) ABSERR = ABSERR0 = atof(getenv("G2_ABSERR"));
    if(getenv("SINCQED_ABREL")) ABREL = atof(getenv("SINCQED_ABREL"));
    if(getenv("SINCQED_ABSKIP")) ABSKIP = atoi(getenv("SINCQED_ABSKIP"));
    if(getenv("SINCQED_ABCHECK")) ABCHECK = atoi(getenv("SINCQED_ABCHECK"));
    if(getenv("SINCQED_NEARF")) NEARF = atof(getenv("SINCQED_NEARF"));
    if(getenv("SINCQED_DDSLACK")) DDSLACK = atof(getenv("SINCQED_DDSLACK"));
    if(getenv("SINCQED_DROPUNRES")) DROPUNRES = atoi(getenv("SINCQED_DROPUNRES"));
    if(getenv("SINCQED_GROW")) GROW = atoi(getenv("SINCQED_GROW"));
    if(getenv("SINCQED_CKPT")) CKPT_EVERY = atof(getenv("SINCQED_CKPT"));
    if(getenv("SINCQED_PROGRESS")) PROG = atof(getenv("SINCQED_PROGRESS"));
    if(argc < 2 || !strcmp(argv[1], "list")){
        printf("%d graphs (one per mirror pair; w = mirror weight), precision fallback %s\n", NALL, QNAME);
        for(int i = 0; i < NALL; i++) printf("  %-8s L=%d  %-22s D=%d w=%d\n", ALL[i]->name, ALL[i]->L, ALL[i]->volkov, ALL[i]->D, ALL[i]->weight);
        printf("usage: %s run h N [eps] [top] GRAPH... | scale GRAPH [kappa] [seed] | compare R1 R2\n", argv[0]);
        return 0;
    }
    if(!strcmp(argv[1], "scale")){
        if(argc < 3) return 1;
        double kap = argc > 3 ? atof(argv[3]) : 24; unsigned seed = argc > 4 ? atoi(argv[4]) : 1;
        for(int i = 0; i < NALL; i++){
            const graph_t *g = ALL[i];
            if(selected(g, argv[2])){ if(g->ptq) scale_test(g, kap, seed); else printf("%-6s %-22s (no scale test for VP graphs)\n", g->name, g->volkov); }
        }
        return 0;
    }
    if(!strcmp(argv[1], "probe")){   /* probe GRAPH: lines of D values z_i on stdin -> F = f(e^z) prod e^z_i in double, |.| sum, and QREAL */
        if(argc < 3) return 1;
        const graph_t *g = find(argv[2]); if(!g){ fprintf(stderr, "no graph %s\n", argv[2]); return 1; }
        double z[MAXD], sf[MAXD]; QREAL sq[MAXD];
        for(;;){
            int ok = 1; for(int i = 0; i < g->D && ok; i++) ok = scanf("%lf", &z[i]) == 1;
            if(!ok) break;
            double w = 1; for(int i = 0; i < g->D; i++){ sf[i] = exp(z[i]); w *= sf[i]; sq[i] = (QREAL)sf[i]; }
            double ab; double v = g->fd(sf, &ab); QREAL abq; QREAL vq = g->fq(sq, &abq);
            printf("%.17g %.6g %.17g %.6g\n", v*w, ab*w, (double)vq*w, (double)abq*w);
        }
        fflush(stdout); return 0;
    }
    if(!strcmp(argv[1], "compare")){
        if(argc < 4){ fprintf(stderr, "compare RESULTS_h RESULTS_h2   (two results files, e.g. h = 1.0 and 1.2)\n"); return 1; }
        return compare(argv[2], argv[3]);
    }
    if(!strcmp(argv[1], "run")){
        if(argc < 5){ fprintf(stderr, "run h N [eps] [top] GRAPH...\n"); return 1; }
        double h = atof(argv[2]); int N = atoi(argv[3]); int a = 4;
        double eps = 1e-11; int top = -1;
        if(a < argc && isnum(argv[a])){ eps = atof(argv[a++]); }
        if(a < argc && isnum(argv[a])){ top = atoi(argv[a++]); }
        if(top < 0){   /* default: the coarsest step 2^top h must resolve the integrand (<= TOPSTEP in z),
                          or whole patches fall between the coarse points and are never refined */
            double ts = getenv("SINCQED_TOPSTEP") ? atof(getenv("SINCQED_TOPSTEP")) : 3.0;
            top = 1; while(top < 2 && (1 << (top+1))*h <= ts*(1 + 1e-9)) top++;
        }
        int nth = 1;
#ifdef _OPENMP
        nth = omp_get_max_threads();
#endif
        const char *lf = getenv("SINCQED_LOG") ? getenv("SINCQED_LOG") : "sincqed.log";
        const char *rf = getenv("SINCQED_RESULTS") ? getenv("SINCQED_RESULTS") : "sincqed_results.txt";
        if(*lf && strcmp(lf, "-")) LOGF = fopen(lf, "a");
        if(*rf && strcmp(rf, "-")){
            FILE *t = fopen(rf, "r"); int fresh = !t; if(t) fclose(t);
            RESF = fopen(rf, "a");
            if(RESF && fresh) fprintf(RESF, "# name     volkov                       L D w      h    N      eps top  value                  err       disc     prune    trunc    round    S_2h            evals        time_s  ref                    diff\n");
        }
        time_t now = time(NULL); char tb[32]; strftime(tb, sizeof tb, "%Y-%m-%d %H:%M:%S", localtime(&now));
        char cmd[512] = ""; for(int i = 0; i < argc; i++){    /* long graph lists are cut with "..." (no overflow) */
            size_t l = strlen(cmd), w = strlen(argv[i]);
            if(l + w + 5 >= sizeof cmd){ strcat(cmd, "..."); break; }
            memcpy(cmd + l, argv[i], w); cmd[l + w] = ' '; cmd[l + w + 1] = 0; }
        const graph_t **sel; int ns = select_graphs(argc, argv, a, &sel);
        T0 = TLAST = wtime(); CURN = ns;
        say("# sincqed %s: %s\n", tb, cmd);
        say("# h=%g N=%d eps=%g top=%d threads=%d quad=%s  graphs=%d  progress every %gs  log=%s  results=%s\n",
            h, N, eps, top, nth, QNAME, ns, PROG, LOGF ? lf : "(none)", RESF ? rf : "(none)");
        { int m = 1 << (top+1), K0 = (N-1)/2, K1 = ((K0 + m - 1)/m)*m;
          if(K1 != K0) say("# note: N=%d adjusted to N=%d (half-width must be a multiple of 2^(top+1)=%d); range |z| <= %g\n", N, 2*K1+1, m, K1*h);
          else say("# range |z| <= %g\n", K1*h);
          if(RESF) fprintf(RESF, "# %s  %s\n# window |z| <= %g\n", tb, cmd, K1*h); }
        double tot = 0, toterr = 0, toterr2 = 0;
        for(int j = 0; j < ns; j++){ CURI = j + 1; run_graph(sel[j], h, N, eps, top, &tot, &toterr, &toterr2); }
        if(ns > 1){
            say("# sum of %d graphs: %+.12f  err %.2e (linear sum)  %.2e (in quadrature)   (%.0fs)\n", ns, tot, toterr, sqrt(toterr2), wtime() - T0);
            if(RESF) fprintf(RESF, "# SUM %d graphs  %+.15e  err %.3e (linear)  %.3e (quadrature)\n", ns, tot, toterr, sqrt(toterr2));
        }
        if(LOGF) fclose(LOGF);
        if(RESF) fclose(RESF);
        return 0;
    }
    fprintf(stderr, "unknown command %s\n", argv[1]); return 1;
}
